/* =========================================================
 *  UX S6: bootstrapUXBindings — 启动时一次性绑定
 * =======================================================*/
function bootstrapUXBindings(){
  try{
    // 1) 最近使用城市回填
    try{
      var lastCity = localStorage.getItem(LAST_CITY_KEY);
      if(lastCity){
        var gzCity=document.getElementById('gz-city');
        if(gzCity && !gzCity.value){
          var opts=gzCity.querySelectorAll('option');
          for(var i=0;i<opts.length;i++){ if(opts[i].text===lastCity){opts[i].selected=true;break;} }
        }
      }
    }catch(_){}
    // 2) Primary Action Zone 4按钮兜底绑定
    try{
      var paz = document.getElementById('primaryActionZone');
      if(paz){
        paz.addEventListener('click', function(e){
          var t = e.target.closest && e.target.closest('[data-paz-action]');
          var act = t && t.getAttribute && t.getAttribute('data-paz-action');
          if(!act) return;
          e.preventDefault();
          if(act==='bazi'){ try{ window.switchTab&&window.switchTab('cn'); window.switchSec&&window.switchSec('cn1'); }catch(_){} }
          else if(act==='tarot'){ try{ window.switchTab&&window.switchTab('wu'); window.switchSec&&window.switchSec('wu1'); setTimeout(function(){var f=window.drawTarotDaily||window.drawTarot;if(f)f(1);},120);}catch(_){} }
          else if(act==='almanac'){ try{ window.switchTab&&window.switchTab('today'); paz.scrollIntoView&&paz.scrollIntoView({behavior:'smooth',block:'start'}); }catch(_){} }
          else if(act==='more'){ try{ window.openQuickCmdPanel&&window.openQuickCmdPanel(); }catch(_){} }
        });
      }
    }catch(_){}
    // 3) beforeunload 草稿不丢提醒
    try{
      window.addEventListener('beforeunload', function(ev){
        var dirty=false;
        try{
          for(var i=0;i<DRAFT_TYPES.length;i++){
            if(localStorage.getItem(DRAFT_KEY_PREFIX+DRAFT_TYPES[i]+DRAFT_DIRTY_SUFFIX)==='1'){dirty=true;break;}
          }
        }catch(_){}
        if(dirty){try{(ev=ev||window.event).returnValue='还有未完成的排盘草稿，离开会丢失，确定要离开吗？';}catch(_){} return '还有未完成的排盘草稿，离开会丢失，确定要离开吗？';}
      });
    }catch(_){}
    // 4) QC 面板键盘绑定
    try{
      var qc = document.getElementById('qc_input');
      if(qc){
        qc.addEventListener('input', function(){
          try{ window.renderQcCandidates && window.renderQcCandidates(qc.value); }catch(_){}
        });
        qc.addEventListener('keydown', function(e){
          if(e.key==='Enter'){ e.preventDefault(); try{ window.runFirstQcMatch && window.runFirstQcMatch(qc.value); }catch(_){} }
          else if(e.key==='Escape'){ try{ window.closeQuickCmdPanel && window.closeQuickCmdPanel(); }catch(_){} }
        });
      }
    }catch(_){}
    // 5) 五格单行快捷输入：注入姓名字段上方
    try{
      if(!document.getElementById('wuge-single-input-wrap')){
        var surnameEl = document.getElementById('wuge-surname');
        if(surnameEl && surnameEl.parentNode){
          var wrap = document.createElement('div');
          wrap.id = 'wuge-single-input-wrap';
          wrap.className = 'wuge-single';
          wrap.innerHTML = '<label style="font-size:12px;color:var(--text-hint);display:block;margin-bottom:4px;">💡 快速：直接输全名（如“张三丰”）自动拆姓+名</label><input id="wuge-single-input" placeholder="例：张三丰 / 欧阳锋 / 李小明" style="width:100%;padding:8px 10px;border-radius:10px;border:1px solid var(--border);font-size:14px;background:var(--bg-card);box-sizing:border-box;">';
          var targetField = surnameEl.closest ? (surnameEl.closest('.field') || surnameEl) : surnameEl;
          surnameEl.parentNode.insertBefore(wrap, targetField);
          var sin = document.getElementById('wuge-single-input');
          if(sin){
            sin.addEventListener('input', function(){
              var v = (sin.value||'').trim();
              if(!v) return;
              var r = null;
              try{ if(window.resolveWugeInput) r = window.resolveWugeInput(v); }catch(_){r=null;}
              if(!r){ r = {surname:v.slice(0,1), given:v.slice(1)}; }
              try{ var s1=document.getElementById('wuge-surname'); if(s1) s1.value = r.surname||''; }catch(_){}
              try{ var n1=document.getElementById('wuge-name'); if(n1) n1.value = r.given||''; }catch(_){}
            });
          }
        }
      }
    }catch(_){}
    // 6) setActiveProfile monkey-patch：记录上次城市 & 记录当前档案
    try{
      var origSetProf = window.setActiveProfile;
      if(typeof origSetProf === 'function'){
        window.setActiveProfile = function(id){
          try{ origSetProf(id); }catch(_){}
          try{
            var p = (window.getActiveProfile && window.getActiveProfile()) || null;
            if(p && p.cityName) localStorage.setItem(LAST_CITY_KEY, p.cityName);
          }catch(_){}
        };
      }
    }catch(_){}
    // 7) 初次启动 UX 版本欢迎 toast
    try{
      var vb = localStorage.getItem('zhiming_v2_ux_ver');
      if(vb !== '2'){
        setTimeout(function(){ try{ window.showToastBottom && window.showToastBottom('✨ 提示：顶部有 4 个常用入口，右上角🔍可打开所有功能'); }catch(_){} }, 1200);
        try{ localStorage.setItem('zhiming_v2_ux_ver','2'); }catch(_){}
      }
    }catch(_){}
  }catch(e){ try{ console.warn('[bootstrapUXBindings]', (e&&e.message)||e); }catch(_){} }
}
try{ window.bootstrapUXBindings = bootstrapUXBindings; }catch(_){}
/* =========================================================
 *  UX S7: runChunked — 分帧跑重任务（避免首屏卡顿）
 * =======================================================*/
function runChunked(tasks){ if(!tasks||!tasks.length)return; var i=0; function next(){ try{ (tasks[i]||function(){})(); }catch(_){} i++; if(i<tasks.length){ var r=window.requestAnimationFrame||function(cb){setTimeout(cb,16);}; r(next); } } next(); }
try{ window.runChunked = runChunked; }catch(_){}
