        {icon:'📝', label:'记录到日记', onclick:"window.openDiaryModal&&window.openDiaryModal()"}
      ];
    } else if(type==='tarot' || type==='塔罗'){
      actions = [
        {icon:'🔀', label:'再抽 3 牌', onclick:"(window.drawTarot||function(){})(3)"},
        {icon:'📓', label:'写日记复盘', onclick:"window.openDiaryModal&&window.openDiaryModal()"},
        {icon:'🏆', label:'准确率排行', onclick:"window.showAccuracyDashboard&&window.showAccuracyDashboard()"}
      ];
    } else if(type==='zhouyi' || type==='周易' || type==='qimen' || type==='奇门'){
      actions = [
        {icon:'📓', label:'写预测复盘', onclick:"window.openDiaryModal&&window.openDiaryModal()"},
        {icon:'🔍', label:'规律关联', onclick:"window.showMyPatterns&&window.showMyPatterns()"},
        {icon:'🎨', label:'生成分享卡', onclick:"window.autoShareCardFromHistory&&window.autoShareCardFromHistory()"}
      ];
    } else {
      actions = [
        {icon:'📝', label:'写日记', onclick:"window.openDiaryModal&&window.openDiaryModal()"},
        {icon:'🏆', label:'看排行榜', onclick:"window.showAccuracyDashboard&&window.showAccuracyDashboard()"},
        {icon:'🔍', label:'所有功能', onclick:"window.openQuickCmdPanel&&window.openQuickCmdPanel()"}
      ];
    }
  }catch(_){ actions = [{icon:'🏠',label:'回到今日',onclick:"window.switchTab&&window.switchTab('today')"}]; }
  return '<div class="result-next-steps"><div class="rns-title">接下来可以…</div><div class="rns-actions">' +
    actions.map(function(a){return '<button class="rns-btn" onclick="'+(a.onclick||'')+'">'+a.icon+' '+a.label+'</button>';}).join('') +
    '</div></div>';
}
